#!/usr/bin/env python3
import subprocess
import sys

def execute_command():
    """Execute system commands from user input."""
    try:
        while True:
            print("Enter command (or 'exit' to quit): ", end="")
            user_input = input().strip()

            if user_input.lower() == 'exit':
                print("Exiting.")
                break

            if not user_input:
                continue

            # Execute the command directly as provided
            result = subprocess.run(user_input, shell=True, capture_output=True, text=True)
            print(result.stdout)
            if result.stderr:
                print("Error:", result.stderr)

    except KeyboardInterrupt:
        print("\nInterrupted.")
        sys.exit(0)

if __name__ == "__main__":
    execute_command()
